<?php

namespace Ediligence\EdiligenceBundle\Repository;

Use Doctrine\ORM\Query\Expr\Join;

/**
 * AffecterRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class TimputDirRepository extends \Doctrine\ORM\EntityRepository {

    public function service_dest($tabimput) {

        $qb = $this->createQueryBuilder('d')
                ->distinct()
                ->addSelect("(case when sc.code_sc Is Not Null then sc.abrv else case when sd.code_sd Is Not Null then sd.abrv else case when dc.code_dc Is Not Null then dc.sigle else case when dg.codeDg Is Not Null then dg.abrv else case when a.matricule Is Not Null Then Concat(a.nom, ' ', a.prenoms, ' ', a.nomJeuneFille) else 1 end end end end end) as service")
                ->leftJoin('AgentBundle:DirectionGenerale', 'dg', Join::WITH, 'd.serviceImput = dg.codeDg')
                ->leftJoin('AgentBundle:Direction', 'dc', Join::WITH, 'd.serviceImput = dc.code_dc')
                ->leftJoin('AgentBundle:SousDirection', 'sd', Join::WITH, 'd.serviceImput = sd.code_sd')
                ->leftJoin('AgentBundle:ServiceDirection', 'sc', Join::WITH, 'd.serviceImput = sc.code_sc')
                ->leftJoin('AgentBundle:Agent', 'a', Join::WITH, 'd.serviceImput = a.matricule')
                ->where('d.imputation In (:tabinput)')
                ->setParameter('tabinput', explode(',', $tabimput))
                ->orderBy('d.imputation', 'ASC');

        //var_dump($qb->getQuery()); 
        return $qb->getQuery()->getResult();
    }

    public function dir_imput($imputation, $service) {

        $qb = $this->createQueryBuilder('i')
                ->select('i.id, i.serviceImput,a.nom, a.prenoms, t tr,'
                        . '(case when sc.code_sc Is Not Null then sc.abrv else case when sd.code_sd Is Not Null then sd.abrv else case when dc.code_dc Is Not Null then dc.sigle else case when dg.codeDg Is Not Null then dg.abrv else dg.abrv end end end end) as service')
                ->leftJoin('AgentBundle:Agent', 'a', Join::WITH, 'i.matriculeimpute = a.matricule')
                ->leftJoin('AgentBundle:DirectionGenerale', 'dg', Join::WITH, 'i.serviceImput = dg.codeDg')
                ->leftJoin('AgentBundle:Direction', 'dc', Join::WITH, 'i.serviceImput = dc.code_dc')
                ->leftJoin('AgentBundle:SousDirection', 'sd', Join::WITH, 'i.serviceImput = sd.code_sd')
                ->leftJoin('AgentBundle:ServiceDirection', 'sc', Join::WITH, 'i.serviceImput = sc.code_sc')
                ->leftjoin('EdiligenceBundle:Tmp_traitement', 't', Join::WITH, 'i.imputation = t.idImput and i.id = t.imputdir')
                ->leftJoin('AgentBundle:Pj', 'p', Join::WITH, 't.pjtraitement = p.id')
                ->where('i.imputation = :imputation And i.serviceImput <>:serviceinput')
                ->setParameter("imputation", $imputation)
                ->setParameter("serviceinput", $service);

        return $qb->getQuery()->getResult();
    }

    public function cord_imput($imputation) {
        $qb = $this->createQueryBuilder('i')
                ->select("i.id, i.serviceImput,a.nom, a.prenoms, t tr,"
                        . "(case when sc.code_sc Is Not Null then sc.abrv else case when sd.code_sd Is Not Null then sd.abrv else case when dc.code_dc Is Not Null then dc.sigle else case when dg.codeDg Is Not Null then dg.abrv else case when a.matricule Is Not Null Then Concat(a.nom, ' ', a.prenoms, ' ', a.nomJeuneFille) else 1 end end end end end) as service")
                ->leftJoin('AgentBundle:Agent', 'a', Join::WITH, 'i.matriculeimpute = a.matricule')
                ->leftJoin('AgentBundle:DirectionGenerale', 'dg', Join::WITH, 'i.serviceImput = dg.codeDg')
                ->leftJoin('AgentBundle:Direction', 'dc', Join::WITH, 'i.serviceImput = dc.code_dc')
                ->leftJoin('AgentBundle:SousDirection', 'sd', Join::WITH, 'i.serviceImput = sd.code_sd')
                ->leftJoin('AgentBundle:ServiceDirection', 'sc', Join::WITH, 'i.serviceImput = sc.code_sc')
                ->leftjoin('EdiligenceBundle:Tmp_traitement', 't', Join::WITH, 'i.imputation = t.idImput and i.id = t.imputdir and t.modif = 0')
                ->leftJoin('AgentBundle:Pj', 'p', Join::WITH, 't.pjtraitement = p.id')
                ->where('i.imputation = :imputation and i.serviceImput <>:coord')
                ->setParameter("imputation", $imputation)
                ->setParameter("coord", 'DC0013');

        return $qb->getQuery()->getResult();
    }

    public function cord_rejet($imputation) {
        $qb = $this->createQueryBuilder('i')
                ->select('i.id, i.serviceImput,a.nom, a.prenoms, t tr,'
                        . '(case when sc.code_sc Is Not Null then sc.abrv else case when sd.code_sd Is Not Null then sd.abrv else case when dc.code_dc Is Not Null then dc.sigle else case when dg.codeDg Is Not Null then dg.abrv else dg.abrv end end end end) as service')
                ->leftJoin('AgentBundle:Agent', 'a', Join::WITH, 'i.matriculeimpute = a.matricule')
                ->leftJoin('AgentBundle:DirectionGenerale', 'dg', Join::WITH, 'i.serviceImput = dg.codeDg')
                ->leftJoin('AgentBundle:Direction', 'dc', Join::WITH, 'i.serviceImput = dc.code_dc')
                ->leftJoin('AgentBundle:SousDirection', 'sd', Join::WITH, 'i.serviceImput = sd.code_sd')
                ->leftJoin('AgentBundle:ServiceDirection', 'sc', Join::WITH, 'i.serviceImput = sc.code_sc')
                ->innerjoin('EdiligenceBundle:Tmp_traitement', 't', Join::WITH, 'i.imputation = t.idImput and i.id = t.imputdir and t.modif = 1')
                ->innerJoin('AgentBundle:Pj', 'p', Join::WITH, 't.pjtraitement = p.id')
                ->where('i.imputation = :imputation and i.serviceImput <>:coord')
                ->setParameter("imputation", $imputation)
