    }

    public function cord_renvoi($imputdir) {

        $qb = $this->createQueryBuilder('i')
                ->select('i.id, i.serviceImput,a.nom, a.prenoms, t tr,'
                        . '(case when sc.code_sc Is Not Null then sc.abrv else case when sd.code_sd Is Not Null then sd.abrv else case when dc.code_dc Is Not Null then dc.sigle else case when dg.codeDg Is Not Null then dg.abrv else dg.abrv end end end end) as service')
                ->leftJoin('AgentBundle:Agent', 'a', Join::WITH, 'i.matriculeimpute = a.matricule')
                ->leftJoin('AgentBundle:DirectionGenerale', 'dg', Join::WITH, 'i.serviceImput = dg.codeDg')
                ->leftJoin('AgentBundle:Direction', 'dc', Join::WITH, 'i.serviceImput = dc.code_dc')
                ->leftJoin('AgentBundle:SousDirection', 'sd', Join::WITH, 'i.serviceImput = sd.code_sd')
                ->leftJoin('AgentBundle:ServiceDirection', 'sc', Join::WITH, 'i.serviceImput = sc.code_sc')
                ->leftjoin('EdiligenceBundle:Tmp_traitement', 't', Join::WITH, 'i.imputation = t.idImput and i.id = t.imputdir')
