    public function diligence($imputation, $traitement) {

        $qb = $this->createQueryBuilder('d')
                ->distinct()
                ->select('d,(case when sc.code_sc Is Not Null then sc.abrv else case when sd.code_sd Is Not Null then sd.abrv else case when dc.code_dc Is Not Null then dc.sigle else case when dg.codeDg Is Not Null then dg.abrv else dg.abrv end end end end) as service')
                ->leftJoin('AgentBundle:DirectionGenerale', 'dg', Join::WITH, 'd.serviceImput = dg.codeDg')
                ->leftJoin('AgentBundle:Direction', 'dc', Join::WITH, 'd.serviceImput = dc.code_dc')
                ->leftJoin('AgentBundle:SousDirection', 'sd', Join::WITH, 'd.serviceImput = sd.code_sd')
                ->leftJoin('AgentBundle:ServiceDirection', 'sc', Join::WITH, 'd.serviceImput = sc.code_sc')
                ->innerJoin('EdiligenceBundle:Timputations', 'i', Join::WITH, 'i.id = d.imputation')
                ->innerJoin('EdiligenceBundle:Ttraitement', 't', Join::WITH, 't.idImput = d.imputation')
                ->where('t.etataff = :etataff And t.etattraitement =:etattraitement And t.modif =:modif And d.imputation In(:imputation) And t.id In(:traitement)')
                ->setParameter("etataff", 1)
                ->setParameter("etattraitement", 0)
                ->setParameter("modif", 0)
                ->setParameter("imputation", $imputation)
                ->setParameter("traitement", $traitement);

        return $qb->getQuery()->getResult();
    }

    public function find_imputdir($service, $mat, $imputation = null) {
        $qb = $this->createQueryBuilder('d')
                ->Where("(d.serviceImput ='" . $service . "' Or d.serviceImput ='" . $mat . "')");
        if ($imputation != null) {
            $qb = $qb->andWhere('d.imputation =:imputation')
                    ->setParameter("imputation", $imputation);
        }
        //dump($qb->getQuery());die;
        return $qb->getQuery()->getResult();
    }

    public function timputdir_search($mat, $service, $etat) {
        $qb = $this->createQueryBuilder('d')
                ->orWhere('d.serviceImput =:service And d.etatImputDir =:etatImputDir')
                ->orWhere('d.serviceImput =:mat And d.etatImputDir =:etatImputDir')
                ->setParameter("service", $service)
                ->setParameter("mat", $mat)
                ->setParameter("etatImputDir", $etat);
        //dump($qb->getQuery()); die;
        return $qb->getQuery()->getResult();
    }

    public function finddest($matriculeImput) {
        $qb = $this->createQueryBuilder('d')
                ->where('d.imputMatricule =:imputMatricule')
                ->setParameter('imputMatricule', $matriculeImput);


        return $qb->getQuery()->getResult();
    }

    public function findFirstImput($codecourrier) {
        $qb = $this->createQueryBuilder('t')
                ->select('t.imputMatricule,i.id as imputationid')
                ->innerJoin('t.imputation', 'i')
                ->innerJoin('i.courrier', 'c')
                ->where('c.id=:codecourrier')
                ->setMaxResults(1)
                ->orderBy('i.id','ASC')
                ->setParameter('codecourrier', $codecourrier);


        return $qb->getQuery()->getOneOrNullResult();
    }

}
